export default async ({ page }) => {
  await page.goto('https://www.ebay.com/itm/307207957660', {waitUntil:'domcontentloaded'});
  const ids = ['177527711396','307207957660','920094126640','198660585568','800736596282','298682121836','267637117893','147140328966','257606606917'];
  const out = await page.evaluate(async (ids) => {
    const r = [];
    for (const id of ids) {
      try {
        const t = await (await fetch('https://www.ebay.com/itm/'+id)).text();
        const m = t.match(/"conditionId":"?(\d+)/) ;
        const c = t.match(/ux-icon-text[^>]*>\s*<span[^>]*>(Condition)/);
        const cond = (t.match(/itemCondition"?:\s*"([^"]+)"/)||[])[1];
        const cd = (t.match(/Condition:?<\/span>.{0,300}?<span[^>]*>([^<]+)</s)||[])[1];
