    return r;
  }, ids);
  return out;
}

export default async ({ page }) => {
  const url='https://www.ebay.com/sch/i.html?_nkw=Sony+WH-1000XM5+black&LH_BIN=1&LH_ItemCondition=1000&_sop=15&_ipg=120&rt=nc';
  await page.goto(url, {waitUntil:'domcontentloaded'});
  await page.waitForTimeout(3000);
  const out = await page.evaluate(() => {
    const cards=[...document.querySelectorAll('li.s-card, li.s-item')];
    return cards.slice(0,40).map(c=>{
      const a=c.querySelector('a[href*="/itm/"]');
      return {href:a&&a.href.split('?')[0], text:c.innerText.replace(/\n+/g,' | ').slice(0,330)};
    });
  });
  return {url:page.url(), n:out.length, out};
}

export default async ({ page }) => {
  const out = await page.evaluate(() => {
    const cards=[...document.querySelectorAll('li.s-card, li.s-item')];
    return cards.map(c=>{
      const a=c.querySelector('a[href*="/itm/"]');
      return {href:a&&a.href.split('?')[0], text:c.innerText.replace(/\n+/g,' | ')};
    });
  });
  const rows=[];
  for (const o of out){
    const t=o.text;
    if(!/1000\s?XM5/i.test(t)) continue;
    if(/hinge|bracket|ear ?pad|cushion|cable|case for|hanger|cover|repair|replacement|part/i.test(t.split('|')[0])) continue;
    const pm=t.match(/\|\s*\$([\d,.]+)(?: to \$[\d,.]+)?\s*\|/);
    const price=pm?parseFloat(pm[1].replace(',','')):null;
    const sm=t.match(/\+\$([\d.]+) delivery/);
    const ship=/Free delivery/.test(t)?0:(sm?parseFloat(sm[1]):null);
    const cond=(t.match(/\|\s*(Brand New|Open box|Pre-Owned|New \(Other\)|Used|Refurbished[^|]*)\s*\|/)||[])[1];
    rows.push({href:o.href,price,ship,total:price!=null&&ship!=null?+(price+ship).toFixed(2):null,cond,bin:/Buy It Now/.test(t),offer:/or Best Offer/.test(t),t:t.slice(0,90),tail:t.slice(-110)});
  }
  rows.sort((a,b)=>(a.total??1e9)-(b.total??1e9));
  return rows.slice(0,20);
}

export default async ({ page }) => {
  await page.goto('https://www.ebay.com/itm/336843067607', {waitUntil:'domcontentloaded'});
  await page.waitForTimeout(2500);
  const info = await page.evaluate(() => {
    const t = document.body.innerText;
    const grab = (re)=> (t.match(re)||[])[0];
    return {
      title: document.title,
      price: grab(/(US )?\$[\d,.]+/),
      buy: /Buy It Now/.test(t), offer: /Make offer/.test(t),
      cond: grab(/Condition:?\s*\n?[^\n]+/),
      ship: grab(/Shipping:?[^\n]*\n?[^\n]*/),
      color: grab(/Color:?\s*\n?[^\n]+/),
      seller: grab(/Seller information[\s\S]{0,200}/),
      slice: t.slice(0,900)
    };
  });
  return info;
}

